using Brutal.ImGuiApi;
using Brutal.ImGuiApi.Backends;
using Brutal.GlfwApi;
using Brutal.VulkanApi;
using Brutal.VulkanApi.Abstractions;
using Brutal.Numerics;
public static class Probe {
 public static void Check(GlfwWindow window, DeviceEx device, Queue queue, VkRenderPass pass, CommandBuffer command, VkSampler sampler, VkImageView view) {
 var context=ImGui.CreateContext(); var glfw=new GlfwBackend(window,GlfwBackend.ClientApi.Vulkan);
 var backend=new VulkanBackend(new VulkanBackend.CreateInfo {Device=device,GraphicsQueue=queue,RenderPass=pass,SubPass=0,MinImageCount=2,ImageCount=3,SampleCount=VkSampleCountFlags._4Bit,DescriptorPoolSize=32});
 var tex=backend.AddTexture(sampler,view,VkImageLayout.ShaderReadOnlyOptimal);
 backend.NewFrame();glfw.NewFrame();ImGui.NewFrame();
 ImGui.GetBackgroundDrawList().AddImage(tex,new float2(0,0),new float2(10,10));
 if(ImGui.Begin("Diagnostic"u8)) {ImGui.Text("Read only"u8); ImGui.Image(tex,new float2(10,10));} ImGui.End();
 bool capture=ImGui.GetIO().WantCaptureMouse || ImGui.GetIO().WantCaptureKeyboard;
 ImGui.Render();backend.RenderDrawData(ImGui.GetDrawData(),command);
 backend.RemoveTexture(tex);backend.Dispose();glfw.Dispose();ImGui.DestroyContext(context);
 }
}

