using System.Reflection;using System.Reflection.Emit;using System.Reflection.Metadata;using System.Reflection.Metadata.Ecma335;using System.Reflection.PortableExecutable;
using var fs=File.OpenRead(args[0]);using var pe=new PEReader(fs);var r=pe.GetMetadataReader();var ops=typeof(OpCodes).GetFields().Where(f=>f.FieldType==typeof(OpCode)).Select(f=>(OpCode)f.GetValue(null)!).ToDictionary(o=>(ushort)o.Value);
string Token(int token){try{var h=MetadataTokens.EntityHandle(token);return h.Kind switch {HandleKind.FieldDefinition=>r.GetString(r.GetFieldDefinition((FieldDefinitionHandle)h).Name),HandleKind.MethodDefinition=>r.GetString(r.GetMethodDefinition((MethodDefinitionHandle)h).Name),HandleKind.MemberReference=>r.GetString(r.GetMemberReference((MemberReferenceHandle)h).Name),_=>token.ToString("X8")};}catch{return token.ToString("X8");}}
foreach(var th in r.TypeDefinitions){var t=r.GetTypeDefinition(th);if(args[1]=="LIST"){Console.WriteLine(r.GetString(t.Name));continue;}if(!r.GetString(t.Name).Contains(args[1]))continue;foreach(var mh in t.GetMethods()){var m=r.GetMethodDefinition(mh);if(m.RelativeVirtualAddress==0)continue;Console.WriteLine("METHOD "+r.GetString(t.Name)+"."+r.GetString(m.Name));var b=pe.GetMethodBody(m.RelativeVirtualAddress).GetILBytes()!;for(int i=0;i<b.Length;){int off=i;ushort code=b[i++];if(code==254)code=(ushort)(0xfe00|b[i++]);var op=ops[code];int n=op.OperandType switch{OperandType.InlineNone=>0,OperandType.ShortInlineBrTarget or OperandType.ShortInlineI or OperandType.ShortInlineVar=>1,OperandType.InlineVar=>2,OperandType.InlineI8 or OperandType.InlineR=>8,OperandType.InlineSwitch=>4+4*BitConverter.ToInt32(b,i),_=>4};string val=n==4?BitConverter.ToInt32(b,i).ToString():Convert.ToHexString(b.AsSpan(i,n));if(op.OperandType is OperandType.InlineField or OperandType.InlineMethod or OperandType.InlineTok or OperandType.InlineType)val=Token(BitConverter.ToInt32(b,i));if(op.OperandType==OperandType.InlineString)val=r.GetUserString(MetadataTokens.UserStringHandle(BitConverter.ToInt32(b,i)&0xffffff));Console.WriteLine($"{off:X4} {op.Name} {val}");i+=n;}}}
